    .reg .b16   %h_in, %h_w, %h_out;
    .reg .f32   %f_acc, %f_in, %f_w;
    .reg .u16   %u16tmp;
    .reg .u32   %g_tid, %g_bdim, %g_cta, %lane, %total;
    .reg .u32   %t, %ow, %oh, %oc, %n;
    .reg .u32   %ic, %kh, %kw;
    .reg .u32   %ih, %iw;
    .reg .u32   %t0, %t1, %t2, %t3;
    .reg .u64   %in_base, %w_base, %out_base, %addr, %off;

