    mov.u32 %g_tid,  %tid.x;
    mov.u32 %g_bdim, %ntid.x;
    mov.u32 %g_cta,  %ctaid.x;
    mad.lo.u32 %g_tid, %g_cta, %g_bdim, %g_tid;

    // Bounds check
    setp.ge.u32 %p0, %g_tid, %total;
    @%p0 bra DONE;

    // Decompose linear index -> (n, oc, oh, ow)
    mov.u32 %t, %g_tid;

    // ow = t % 222; t = t / 222
    rem.u32 %ow, %t, 222;
    div.u32 %t,  %t, 222;

    // oh = t % 222; t = t / 222
    rem.u32 %oh, %t, 222;
    div.u32 %t,  %t, 222;

    // oc = t % 32;  n = t / 32
    rem.u32 %oc, %t, 32;
    div.u32 %n,  %t, 32;

    // Accumulator
    mov.f32 %f_acc, 0f00000000;

    // Loop ic = 0..2
    mov.u32 %ic, 0;
L_ic:
    setp.ge.u32 %p1, %ic, 3;
    @%p1 bra L_ic_done;

    // Loop kh = 0..2
    mov.u32 %kh, 0;
L_kh:
    setp.ge.u32 %p2, %kh, 3;
    @%p2 bra L_kh_done;

    // Loop kw = 0..2
    mov.u32 %kw, 0;
L_kw:
    setp.ge.u32 %p3, %kw, 3;
    @%p3 bra L_kw_done;

