    mul.lo.u32 %t0, %n, 3;
    add.u32    %t0, %t0, %ic;
    mul.lo.u32 %t0, %t0, 224;
    add.u32    %t0, %t0, %ih;
    mul.lo.u32 %t0, %t0, 224;
    add.u32    %t0, %t0, %iw;
    cvt.u64.u32 %off, %t0;
