    mul.lo.u32 %t3, %t3, 3;
    add.u32    %t3, %t3, %kh;
    mul.lo.u32 %t3, %t3, 3;
    add.u32    %t3, %t3, %kw;
    cvt.u64.u32 %off, %t3;
    shl.b64     %off, %off, 1;          // *2 bytes (bf16)
    add.u64     %addr, %w_base, %off;
    ld.global.u16 %h_w, [%addr];
    cvt.f32.bf16 %f_w, %h_w;

    // Accumulate
    fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;

